// Package importer loads a SQL script generated by SSMS into the local
// database named in a Kairo config.ini: it empties the database, then runs
// the script batch by batch. Jobs of a run go one after another.
package importer

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"actualizador/internal/migrator"
	"actualizador/internal/silent"
	"actualizador/internal/sqlscript"
)

// EventName is the Wails event that carries progress to the UI.
const EventName = "importer:event"

// defaultUsername is the login used on every machine; the Usuario of the
// config.ini is ignored on purpose.
const defaultUsername = "kong"

const progressInterval = 250 * time.Millisecond

const excerptLength = 200

// Job is one row of the screen: a Kairo folder and the script to load.
type Job struct {
	ID        string `json:"id"`
	KairoPath string `json:"kairoPath"`
	SqlPath   string `json:"sqlPath"`
}

// PlannedJob is what a Job would do, checked without touching any database.
// An empty Error means the job can run.
type PlannedJob struct {
	ID        string `json:"id"`
	Server    string `json:"server"`
	Database  string `json:"database"`
	Username  string `json:"username"`
	SqlPath   string `json:"sqlPath"`
	SizeBytes int64  `json:"sizeBytes"`
	// IsNew is true when the database does not exist yet and Run will create
	// it. False also when the server could not be asked (Run then reports why).
	IsNew bool   `json:"isNew"`
	Error string `json:"error"`
}

// JobResult is the outcome of one job of Run.
type JobResult struct {
	ID       string   `json:"id"`
	IsDone   bool     `json:"isDone"`
	Batches  int      `json:"batches"`
	Warnings []string `json:"warnings"`
	Error    string   `json:"error"`
}

// Event reports progress to the UI.
type Event struct {
	JobID string `json:"jobId"`
	// Kind: "job-start", "progress", "info", "warning", "job-done", "job-error".
	Kind       string `json:"kind"`
	BytesDone  int64  `json:"bytesDone"`
	BytesTotal int64  `json:"bytesTotal"`
	Message    string `json:"message"`
}

// Service is the Wails-bound entry point of the importer.
type Service struct {
	baseDir  string
	password string
	// username is "kong"; tests set it empty to use the Windows login.
	username string
	emit     func(Event)

	mutex     sync.Mutex
	isRunning bool
}

// NewService writes its log to <baseDir>\Logs\import.log. password is the one
// of the kong login. emit forwards events to the UI and may be nil.
func NewService(baseDir, password string, emit func(Event)) *Service {
	return &Service{baseDir: baseDir, password: password, username: defaultUsername, emit: emit}
}

// IsRunning reports whether an import is in progress. The window uses it to
// ask before closing.
func (service *Service) IsRunning() bool {
	service.mutex.Lock()
	defer service.mutex.Unlock()

	return service.isRunning
}

// Plan checks every job and reports where it would import. Nothing is
// touched. The second job that points at the same database as an earlier one
// gets an error.
func (service *Service) Plan(jobs []Job) []PlannedJob {
	planned := make([]PlannedJob, len(jobs))
	rowOfDatabase := map[string]int{}

	for index, job := range jobs {
		planned[index] = service.planJob(job)

		if planned[index].Error != "" {
			continue
		}

		key := databaseKey(planned[index].Server, planned[index].Database)

		if first, isDuplicate := rowOfDatabase[key]; isDuplicate {
			planned[index].Error = fmt.Sprintf("misma base de datos que la fila %d: una borraría lo que importó la otra", first)
			continue
		}

		rowOfDatabase[key] = index + 1
	}

	return planned
}

func (service *Service) planJob(job Job) PlannedJob {
	planned := PlannedJob{ID: job.ID, SqlPath: job.SqlPath, Username: service.username}

	iniPath, err := resolveIniPath(job.KairoPath)
	if err != nil {
		planned.Error = err.Error()
		return planned
	}

	connection, err := silent.ReadConnection(iniPath)
	if err != nil {
		planned.Error = err.Error()
		return planned
	}

	planned.Server = connection.Server
	planned.Database = connection.Database

	if !migrator.IsLocalServer(connection.Server) {
		planned.Error = fmt.Sprintf("el servidor %s no es local: solo se importa en el equipo propio", connection.Server)
		return planned
	}

	if strings.TrimSpace(job.SqlPath) == "" {
		planned.Error = "falta el fichero .sql"
		return planned
	}

	info, err := os.Stat(job.SqlPath)
	if err != nil || info.IsDir() {
		planned.Error = fmt.Sprintf("no se encuentra el fichero .sql %s", job.SqlPath)
		return planned
	}

	planned.SizeBytes = info.Size()

	exists, err := migrator.DatabaseExists(service.connectionParams(planned))
	planned.IsNew = err == nil && !exists

	return planned
}

// resolveIniPath accepts the Kairo folder or the config.ini itself.
func resolveIniPath(kairoPath string) (string, error) {
	kairoPath = strings.TrimSpace(kairoPath)

	if kairoPath == "" {
		return "", errors.New("falta la carpeta de Kairo")
	}

	iniPath := kairoPath
	if !strings.EqualFold(filepath.Ext(kairoPath), ".ini") {
		iniPath = filepath.Join(kairoPath, "config.ini")
	}

	if info, err := os.Stat(iniPath); err != nil || info.IsDir() {
		return "", fmt.Errorf("no se encuentra %s", iniPath)
	}

	return iniPath, nil
}

// databaseKey is the same for the spellings of one local server.
func databaseKey(server, database string) string {
	hostPart, instance, _ := strings.Cut(strings.TrimSpace(server), `\`)
	host, _, _ := strings.Cut(hostPart, ",")
	host = strings.TrimPrefix(strings.ToLower(strings.TrimSpace(host)), "tcp:")

	if migrator.IsLocalServer(host) {
		host = "local"
	}

	return strings.ToLower(host + `\` + strings.TrimSpace(instance) + "|" + strings.TrimSpace(database))
}

// Run imports every job, one after another. A job that fails does not stop
// the next. The error is only for a run that could not start.
func (service *Service) Run(jobs []Job, options migrator.ApplyOptions) ([]JobResult, error) {
	service.mutex.Lock()

	if service.isRunning {
		service.mutex.Unlock()
		return nil, errors.New("hay una importación en curso")
	}

	if service.username != "" && service.password == "" {
		service.mutex.Unlock()
		return nil, errors.New("esta compilación no incluye la contraseña de kong (falta KAIRO_SILENT_PASSWORD al compilar)")
	}

	service.isRunning = true
	service.mutex.Unlock()

	defer func() {
		service.mutex.Lock()
		service.isRunning = false
		service.mutex.Unlock()
	}()

	planned := service.Plan(jobs)
	results := make([]JobResult, len(planned))

	for index, job := range planned {
		results[index] = service.runJob(job, options)
	}

	return results, nil
}

func (service *Service) runJob(job PlannedJob, options migrator.ApplyOptions) JobResult {
	result := JobResult{ID: job.ID, Warnings: []string{}}

	fail := func(err error) JobResult {
		result.Error = err.Error()
		service.publish(Event{JobID: job.ID, Kind: "job-error", Message: result.Error})

		return result
	}

	if job.Error != "" {
		return fail(errors.New(job.Error))
	}

	service.publish(Event{JobID: job.ID, Kind: "job-start", BytesTotal: job.SizeBytes,
		Message: fmt.Sprintf("Importando %s en %s / %s", filepath.Base(job.SqlPath), job.Server, job.Database)})

	// Read the whole script once before emptying anything: a file that cannot
	// be read or has no statements must not cost the database.
	if err := checkScript(job.SqlPath); err != nil {
		return fail(err)
	}

	params := service.connectionParams(job)

	isCreated, err := migrator.EnsureDatabase(params)
	if err != nil {
		return fail(err)
	}

	if isCreated {
		service.publish(Event{JobID: job.ID, Kind: "info", Message: fmt.Sprintf("Base de datos %s creada", job.Database)})
	}

	runner, closeAll, err := migrator.Open(params, func(event migrator.Event) {
		if event.Kind != "error" {
			service.publish(Event{JobID: job.ID, Kind: "info", Message: event.Message})
		}
	})
	if err != nil {
		return fail(err)
	}
	defer closeAll()

	ctx := context.Background()

	if err := runner.Clean(ctx, options); err != nil {
		return fail(err)
	}

	file, err := os.Open(job.SqlPath)
	if err != nil {
		return fail(err)
	}
	defer file.Close()

	counter := &countingReader{source: file}
	lastProgress := time.Now()

	err = sqlscript.ReadBatches(counter, func(batch sqlscript.Batch) error {
		if batch.IsSkipped {
			return nil
		}

		if execErr := runner.ExecBatch(ctx, batch.Text); execErr != nil {
			if !batch.IsPrincipal {
				return fmt.Errorf("lote %d: %w\n%s", batch.Number, execErr, excerpt(batch.Text))
			}

			warning := fmt.Sprintf("lote %d: %v (%s)", batch.Number, execErr, excerpt(batch.Text))
			result.Warnings = append(result.Warnings, warning)
			service.publish(Event{JobID: job.ID, Kind: "warning", Message: warning})

			return nil
		}

		result.Batches++

		if time.Since(lastProgress) >= progressInterval {
			lastProgress = time.Now()
			service.publish(Event{JobID: job.ID, Kind: "progress", BytesDone: counter.count(), BytesTotal: job.SizeBytes})
		}

		return nil
	})
	if err != nil {
		return fail(err)
	}

	// The login that imports must be able to use the database afterwards.
	changed, accessErr := runner.EnsureOwnAccess(ctx)

	switch {
	case accessErr != nil:
		warning := fmt.Sprintf("no se pudo dar acceso al login %s en la base de datos: %v", service.loginName(), accessErr)
		result.Warnings = append(result.Warnings, warning)
		service.publish(Event{JobID: job.ID, Kind: "warning", Message: warning})
	case changed:
		service.publish(Event{JobID: job.ID, Kind: "info", Message: fmt.Sprintf("Usuario %s creado en la base de datos con rol db_owner", service.loginName())})
	}

	result.IsDone = true
	service.publish(Event{JobID: job.ID, Kind: "job-done", BytesDone: job.SizeBytes, BytesTotal: job.SizeBytes,
		Message: fmt.Sprintf("Importado: %d lotes, %d aviso(s)", result.Batches, len(result.Warnings))})

	return result
}

// loginName is for messages: empty username means the Windows login (tests).
func (service *Service) loginName() string {
	if service.username == "" {
		return "de Windows"
	}

	return service.username
}

func (service *Service) connectionParams(job PlannedJob) migrator.ConnectionParams {
	return migrator.ConnectionParams{Server: job.Server, Database: job.Database, Username: service.username, Password: service.password}
}

// checkScript reads the script to the end without running anything.
func checkScript(path string) error {
	file, err := os.Open(path)
	if err != nil {
		return err
	}
	defer file.Close()

	return sqlscript.ReadBatches(file, func(sqlscript.Batch) error { return nil })
}

func excerpt(text string) string {
	text = strings.Join(strings.Fields(text), " ")

	if len(text) > excerptLength {
		return text[:excerptLength] + "..."
	}

	return text
}

// countingReader counts the bytes read, for the progress bar.
type countingReader struct {
	source io.Reader
	bytes  atomic.Int64
}

func (reader *countingReader) Read(target []byte) (int, error) {
	count, err := reader.source.Read(target)
	reader.bytes.Add(int64(count))

	return count, err
}

func (reader *countingReader) count() int64 {
	return reader.bytes.Load()
}

// publish writes the event to Logs\import.log and forwards it to the UI.
func (service *Service) publish(event Event) {
	service.writeLog(event)

	if service.emit != nil {
		service.emit(event)
	}
}

func (service *Service) writeLog(event Event) {
	if event.Kind == "progress" {
		return
	}

	dir := filepath.Join(service.baseDir, "Logs")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return
	}

	file, err := os.OpenFile(filepath.Join(dir, "import.log"), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
	if err != nil {
		return
	}
	defer file.Close()

	fmt.Fprintf(file, "%s [%s] %s %s\n", time.Now().Format("2006-01-02 15:04:05"), event.Kind, event.JobID, event.Message)
}
